def _seed_demo_product_areas() -> None:
    workspace_id = op.get_bind().scalar(sa.text("SELECT id FROM workspaces WHERE slug = 'demo'"))
    if workspace_id is None:
        return
    product_areas = sa.table(
        "product_areas",
        sa.column("workspace_id", sa.BigInteger()),
        sa.column("slug", sa.String()),
        sa.column("name", sa.String()),
        sa.column("description", sa.Text()),
    )
    op.bulk_insert(
        product_areas,
        [
            {"workspace_id": workspace_id, "slug": slug, "name": name, "description": description}
            for slug, name, description in DEMO_PRODUCT_AREAS
        ],
    )


